STRING        = QUOTE { TEXT | ESCAPE | "{{" | "}}" | Interpolation } QUOTE
              | RAW_STRING ;
RAW_STRING    = "#" QUOTE { any character except a line break } QUOTE "#" ;  (* ends at the first "#; no escapes, no interpolation *)
ESCAPE        = "\" ( QUOTE | "\" | "n" | "t" | "u{" HEX { HEX } "}" ) ;     (* 1–6 hex digits, a valid scalar *)
Interpolation = "{" Expr { "," WORD ":" Expr } "}" ;                       (* §2.3; format options §4.11 *)
TEXT          = any characters except QUOTE, "\", "{", "}", line breaks ;

public struct Token: Sendable, Hashable {
    public var kind: TokenKind              // §1.4–§1.8, plus eof
    public var text: String                 // exactly as written (full-width characters kept)
    public var leadingTrivia: [Trivia]      // ownership rules: §3.2
    public var trailingTrivia: [Trivia]
    public var presence: Presence           // .present, or .missing (inserted by recovery, empty text)
    public var flags: TokenFlags            // fullWidth, keywordCaseVariant, foreign, unitDiagnosed, windowsPath, raw
    public var unit: UnitSpelling?          // for numbers with a unit
}

public enum Trivia: Sendable, Hashable {
    case spaces(Int), tabs(Int)
    case newline(NewlineKind)               // .lf, .crlf, .cr
    case lineComment(String), blockComment(String)
    case unusualSpace(String), invisible(String)
    case byteOrderMark
}

(* ---------- file ---------- *)
File              = { TopLevel } EOF ;
TopLevel          = InfoBlock | PackageBlock | OptionsBlock | WidgetBlock
                  | StyleDecl | TranslationsBlock | ComponentDecl | ScriptBlock
                  | StrayStatement ;                                     (* checked as DK2034 / DK2015, §2.1 *)
InfoBlock         = "info" Block ;
PackageBlock      = "package" Block ;
OptionsBlock      = "options" Block ;                                    (* sets the options context, below *)
WidgetBlock       = "widget" Block ;
StyleDecl         = "style" IDENT Block ;
TranslationsBlock = "translations" Block ;
StrayStatement    = Statement ;

(* ---------- blocks: one body for every kind ---------- *)
Block             = "{" Body "}" ;
Body              = [ Statement { Sep Statement } [ Sep ] ] ;
Sep               = ";" | "," | NL ;                                     (* ";" and "," are hard (N2) *)
Statement         = Declaration | IfStmt | ForStmt | Field | Entry | Group
                  | OptionDecl | Assignment | CallStmt | ModifierStmt
                  | StyleDecl | ComponentDecl ;                         (* inside a block: DK2014, "move out", §2.6 *)

Declaration       = ( "variable" | "saved" | "computed" ) IDENT "=" Expr ;
IfStmt            = "if" Expr Block [ "else" ( IfStmt | Block ) ] { ModifierApp } ;   (* modifiers: DK2032 *)
ForStmt           = "for" IDENT "in" Expr Block { ModifierApp } ;                     (* modifiers: DK2032 *)
Field             = WORD ":" Expr ;                          (* info, package; elsewhere DK2014 / DK2036 *)
Entry             = STRING ( ":" | "=" ) Expr ;              (* a translation; "=" accepted, formatter writes ":" *)
Group             = STRING [ ":" ] Block ;                   (* a language block; ":" accepted, formatter removes it *)
OptionDecl        = Target "=" CallStmt ;                    (* only in the options context *)
Assignment        = Target "=" Expr ;                        (* outside the options context *)
Target            = ( IDENT | UIDENT ) [ "." WORD ] ;        (* x, options.x, volume.level; UIDENT only for DK3016 *)
CallStmt          = Callee [ ArgClause ] [ Block ] { ModifierApp } ;
Callee            = ( UIDENT | IDENT ) { "." WORD } ;        (* Text, Section, open, music.next, weather.at *)
ModifierStmt      = ModifierApp { ModifierApp } ;            (* a chain with no element before it: style, .hover *)
ModifierApp       = "." WORD [ ArgClause ] [ Block ] ;       (* may begin after NL: N3 *)
ArgClause         = "(" [ ArgList ] ")" ;                    (* "(" on the same line, N7 *)

(* ---------- reserved (deskVersion 1 rejects them after parsing) ---------- *)
ComponentDecl     = "component" UIDENT "(" [ Param { "," Param } [ "," ] ] ")" Block ;
Param             = IDENT [ ":" UIDENT ] [ "=" Expr ] ;
ScriptBlock       = "script" OPAQUE_BLOCK ;
(* OPAQUE_BLOCK: from "{" to its matching "}", counting braces while skipping JavaScript strings ('…', "…",
   `…` with ${…} nesting) and comments; lexed as one token so the file still round-trips. *)

(* ---------- expressions: precedence from low to high, §2.9 ---------- *)
Expr              = Ternary ;
Ternary           = Or [ "?" Expr ":" Expr ] ;                           (* right-associative *)
Or                = And { "or" And } ;
And               = Not { "and" Not } ;
Not               = "not" Not | Compare ;
Compare           = Range [ CompareOp Range ] ;                          (* not chainable: DK2025 *)
CompareOp         = "==" | "!=" | "<" | "<=" | ">" | ">=" ;
Range             = Sum [ "..." Sum ] ;
Sum               = Product { ( "+" | "-" ) Product } ;
Product           = Prefix { ( "*" | "/" | "%" ) Prefix } ;
Prefix            = "-" Prefix | Postfix ;
Postfix           = Primary { "." WORD | ArgClause } ;
Primary           = NUMBER | STRING | "true" | "false" | IDENT | UIDENT
                  | "." WORD [ ArgClause ]                               (* implicit member: .caption, .glass *)
                  | "[" [ Expr { "," Expr } [ "," ] ] "]"
                  | "(" Expr ")" ;
ArgList           = Arg { "," Arg } [ "," ] ;
Arg               = [ WORD ":" ] Expr ;                                  (* a label may be a keyword: if: *)
                                                                         (* WORD "=" Expr is parsed for recovery: DK2035 / DK2037 *)

(* ---------- token classes ---------- *)
WORD              = IDENT | UIDENT | keyword ;                           (* member names and labels *)

