public struct SyntaxTree: Sendable {
    public let file: DeskFileID               // which file (§0.4); diagnostics and edits carry it
    public let root: SyntaxNode               // kind .sourceFile; its last child is the eof token
    public let text: String                   // the text it was parsed from
    public let version: Int                   // increases with every parse of this file; part of NodeID (§4.20)
    public let diagnostics: [Diagnostic]      // DK1xxx, DK2xxx and parser-level DK9xxx, sorted by position
    public let header: FileHeader             // deskVersion and info.requires, read by a syntax-only pass (§8.5)
    public var description: String { get }   // the printer: == text for every input (§3.5)
    public func node(at offset: Int) -> SyntaxNode?
    public func location(of offset: Int) -> SourceLocation
}

public struct FileHeader: Sendable, Hashable {  // read from the tree alone, before migration or checking (§8.5)
