public struct MenuItemNode: Sendable, Equatable {
    public var title: DeskExpr                              // usually .localized
    public var checked: Binding; public var enabled: Binding
    public var actions: [Action]                            // its .onClick
    public var submenu: [MenuNode]                          // Menu { }
}
public struct MenuIf: Sendable, Equatable { public var branches: [MenuBranch]; public var otherwise: [MenuNode] }
public struct MenuBranch: Sendable, Equatable { public var condition: Binding; public var body: [MenuNode] }
public struct MenuFor: Sendable, Equatable {
    public var source: Binding; public var item: SlotID; public var body: [MenuNode]
}

public indirect enum Binding: Sendable, Equatable {         // DESK-RUNTIME §3.5 plus:
    case constant(OptionValueIR)
    case template(Template)                                 // Rainmeter only
    case expr(Expr)                                         // Rainmeter only: formula AST
    case desk(DeskExpr, deps: [DepKey])                     // Desk expression with its dependencies
    case conditional([ConditionalCase], otherwise: Binding)
    case sampled(Binding, SamplePolicy)                     // Rainmeter only
    case inherited                                          // Desk: the effective value of the nearest ancestor that
                                                            // has any candidate for this facet, evaluated at run time,
                                                            // recursively; the catalog default at the root (§4.8.6)
}
public struct ConditionalCase: Sendable, Equatable {
    public var when: CaseCondition                          // .expr(DeskExpr) | .hover | .pressed | .all([CaseCondition])
    public var value: Binding
    public var origin: Origin                               // .own(range) | .style(name, range) — for the editor
}

public indirect enum DeskExpr: Sendable, Equatable {
    case number(Double, DimensionIR)
    case string(String)                                     // text that is never translated (paths, patterns, log text)
    case bool(Bool), color(ColorIR), enumCase(type: String, case: String)
    case missing                                            // a poisoned declaration or a dropped option (§4.1)
    case list([DeskExpr]), range(DeskExpr, DeskExpr)
    case template([TemplatePart])                           // interpolated text that is never translated (web addresses)
    case localized(LocalizedKey, values: [FormattedValue])  // translatable text (§8.6): the key is the whole string
    case variable(SlotID), computed(SlotID), option(OptionID), loopItem(SlotID), event(String)
    case data(DataNodeRef, path: [String])                  // a field of a data node
    case geometry(TemplateID, GeometryField)                // Freeform sibling edge
    case widgetSize(String)
    case unary(DeskUnary, DeskExpr)
    case binary(DeskBinary, DeskExpr, DeskExpr, result: DimensionIR)
    case ternary(DeskExpr, DeskExpr, DeskExpr)
    case call(FunctionID, [DeskExpr])                       // pure functions and members (§5.9)
    case member(DeskExpr, String)                           // record field, list projection, Json member
    case ifMissing(DeskExpr, DeskExpr), isMissing(DeskExpr)
}
public enum TemplatePart: Sendable, Equatable { case text(String), value(FormattedValue) }
public struct FormattedValue: Sendable, Equatable { public var expr: DeskExpr; public var format: FormatSpec }
public struct LocalizedKey: Sendable, Hashable { public var text: String }   // the canonical source text (§8.6)

public struct TranslationTable: Sendable, Equatable {       // §8.6; the language is picked when the widget loads
    public var source: [LocalizedKey: [PatternPart]]         // the original, as written
    public var languages: [String: [LocalizedKey: [PatternPart]]]   // canonical BCP 47 tag → key → translation
}
public enum PatternPart: Sendable, Equatable {
    case text(String)
    case placeholder(Int)                                   // index into the `values` of .localized, in the original's order
}

public struct DimensionIR: Sendable, Equatable { public var dimension: String; public var displayBase: Int? }
public indirect enum DeskTypeIR: Sendable, Equatable {       // DeskType (§5.1) without references into DeskLanguage
    case number(DimensionIR), string, bool, color, paint, date, json, secret, size
    case imageSource, symbolName, fontFamily, folderPath
    case enumeration(String), record(String), list(DeskTypeIR)
}
public struct FormatSpec: Sendable, Equatable {             // everything §4.11 decides at compile time
    public var dimension: DimensionIR                       // with the display base settled for bytes
    public var style: FormatStyle                           // the member's default (catalog), or `style:` / `format:`
    public var decimals: Int?                               // nil: the dimension's rule of §4.11
    public var unit: FormatUnit                             // .auto, or a fixed unit written in the text
    public var unitStyle: UnitStyle                         // .short by default
    public var bits: Bool
    public var equalWidthDigits: Bool                       // interpolated digits (§4.11)
    public var missing: DeskExpr?                           // the `missing:` text; a .localized when translatable
}
// Left to run time on purpose: `.auto` units (°C or °F, km/h or mph, mm or in, hPa or inHg), locale separators and
// the display language — they follow the Mac's settings (§4.11, §8.6).

public enum Action: Sendable, Equatable {                   // Desk's actions. The DESK-RUNTIME §8.2 cases that take a
                                                            // Template (.open, .log, .system(.setClip), .meterVisibility
                                                            // by static name) stay for converted skins only.
    case assign(AssignTarget, DeskExpr)                     // .slot(SlotID) | .option(OptionID) | .settable(DataNodeRef, field)
    case ifElse([ActionBranch], otherwise: [Action])
    case forEach(DeskExpr, item: SlotID, body: [Action])
    case after(delay: DeskExpr, captures: [SlotID], body: [Action])   // loop variables and `event` by value (§4.17)
    case open(DeskExpr)                                     // user-initiated
    case copy(DeskExpr)                                     // user-initiated
    case log(DeskExpr)
    case notify(title: DeskExpr, message: DeskExpr)
    case visibility(VisibilityOp, target: VisibilityTarget) // show / hide / showOrHide
    case dataCommand(DataNodeRef, command: String, arguments: [DeskExpr])   // music.next(), weather.refresh(), trash.empty()
    case run(CommandIR)                                     // user-initiated
    case lifecycle(Lifecycle), ui(UIRequest)                // widget.reload() → .refresh; widget.openOptions(), widget.edit()
}
public struct ActionBranch: Sendable, Equatable { public var condition: DeskExpr; public var body: [Action] }
public enum VisibilityOp: Sendable, Equatable { case show, hide, showOrHide }
public enum VisibilityTarget: Sendable, Equatable {
    case template(TemplateID)                               // a bare own name, resolved at compile time
    case name(DeskExpr)                                     // a String that names the element at run time (§4.10)
}
public struct CommandIR: Sendable, Equatable {              // §8.2
    public var script: String                               // the author's text; each placeholder replaced by "${n}" / ${n}
    public var arguments: [DeskExpr]                        // the placeholders' values, in order: $1, $2, …
    public var scriptOption: OptionID?                      // a whole-command option: its value is the script
    public var timeout: Double
}

extension DataNode {                                        // Desk field
    // desk: DeskDataNode?                nil for converted skins; the kernel's OptionStack is synthesized from the
    //                                    catalog's DataLowering and the arguments (§7.4)
}
public struct DeskDataNode: Sendable, Equatable {
    public var member: String                               // catalog path: "cpu.core", "calendar.month"
    public var arguments: [String: Binding]                 // by parameter label ("_" for positional), lowered and
                                                            // name-resolved; the node's key (§7.4)
    public var cadence: CadenceIR                           // .periodic(seconds:, aligned:) | .clock(precision) | .event
                                                            // | .frame | .service | .once
    public var usage: DataUsage                             // .display | .logic | .onDemand (§4.18)
    public var instanceScope: TemplateID?                   // the innermost `for` whose loop variable an argument reads
    public var permission: String?                          // for the refused-permission badge
}

